#!/usr/bin/env python3
"""Bundle the plugin's pure UI models for the standalone canvas prototype."""

import argparse
from pathlib import Path
import re


ROOT = Path(__file__).resolve().parents[1]
MODULES = ("model", "facts", "consolefacts", "reveal")
OUTPUT = ROOT / "prototypes/student-ui-canvas-core.js"


def bundle():
    chunks = [
        "// Generated by devtools/build_canvas_core.py; edit the source modules, not this file.\n",
        'window.CanvasCore = (() => {\n"use strict";\nconst modules = {};\n',
    ]
    for name in MODULES:
        source = (ROOT / f"plugin/amd/src/{name}.js").read_text()
        exports = re.findall(r"^export (?:const|function|class) (\w+)", source, re.M)

        def dependency(match):
            fields, module = match.groups()
            if module not in MODULES:
                raise ValueError(f"Unsupported dependency: {module}")
            return f"const {{{fields}}} = modules.{module};"

        source = re.sub(
            r"^import\s*\{([^}]+)\}\s*from ['\"]mod_gns3lab/(\w+)['\"];",
            dependency, source, flags=re.M,
        )
        source = re.sub(r"^export (?=const|function|class)", "", source, flags=re.M)
        if re.search(r"^(?:import|export)\s", source, re.M):
            raise ValueError(f"Unsupported module syntax in {name}")
        chunks.extend([
            f"modules.{name} = (() => {{\n", source,
            "\nreturn {" + ", ".join(exports) + "};\n})();\n",
        ])
    return "".join(chunks) + "return modules;\n})();\n"


if __name__ == "__main__":
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--check", action="store_true", help="Fail if the bundle is outdated")
    args = parser.parse_args()
    content = bundle()
    if args.check:
        if not OUTPUT.exists() or OUTPUT.read_text() != content:
            parser.exit(1, "Canvas core is outdated; run python3 devtools/build_canvas_core.py\n")
        print("Canvas core matches the plugin sources")
    else:
        OUTPUT.write_text(content)
        print(f"Built {OUTPUT.relative_to(ROOT)}")
